rm -rf /tmp/qa_twin43 && mkdir -p /tmp/qa_twin43/bin && cp -r ../soc-ap ../test_harness /tmp/qa_twin43/ && rm -rf /tmp/qa_twin43/soc-ap/build && ([ -e /tmp/qa_twin43/soc-ap/third_party/install ] || (mkdir -p /tmp/qa_twin43/soc-ap/third_party && ln -s /usr/local /tmp/qa_twin43/soc-ap/third_party/install)) && cd /tmp/qa_twin43/soc-ap && bash tools/deploy_twin.sh --build-only && ctest --test-dir build/forward --output-on-failure && python3 ../test_harness/static_checks/cascade/run_query_cases.py --test-host build/host/soc-ap --cases ../test_harness/test_cases/cascade/query_cases.json && python3 -c "import pathlib; pathlib.Path("/tmp/test_serial_baud.cpp").write_text("#include <cassert>
#include <cstdio>
#include <cstdlib>
#include <fcntl.h>
#include <unistd.h>
#include \"serial_posix.h\"
#include \"query.h\"
int main() {
  minimc::SerialConfig dflt;
  assert(dflt.baud_rate == 921600U);
  minimc::QueryOptions qdflt;
  assert(qdflt.baud_rate == 921600U);
  int mfd = posix_openpt(O_RDWR | O_NOCTTY);
  assert(mfd >= 0 && grantpt(mfd) == 0 && unlockpt(mfd) == 0);
  const char* pts = ptsname(mfd);
  assert(pts != nullptr);
  minimc::SerialContext ctx;
  minimc::SerialConfig bad{pts, 123456U};
  assert(!minimc::serial_open(&bad, &ctx) && !ctx.is_open && ctx.fd == -1);
  const uint32_t bauds[] = {921600U, 460800U, 115200U};
  for (uint32_t b : bauds) {
    minimc::SerialConfig ok{pts, b};
    assert(minimc::serial_open(&ok, &ctx) && ctx.is_open && ctx.fd >= 0);
    minimc::serial_close(&ctx);
    assert(!ctx.is_open && ctx.fd == -1);
  }
  close(mfd);
  printf(\"[PASS] serial_posix baud_to_speed & serial_open positive(921600/460800/115200) and negative(123456) verified\\n\");
  return 0;
}
")" && g++ -std=c++17 -O2 -Wall -Wextra -Werror -I core/forward/transport -I core/forward/minimc -I core/host core/forward/transport/serial_posix.cpp /tmp/test_serial_baud.cpp -o /tmp/test_serial_baud && /tmp/test_serial_baud && (! ./build/host/soc-ap --port /dev/null --baud 123456 --target mc --cmd version) && echo "[PASS] parse_baud_rate rejected invalid baud 123456"
